function longestRepeatingSubstring(s) {
  const n = s.length;
  let prev = new Array(n + 1).fill(0);
  let best = 0;

  for (let i = 1; i <= n; i++) {
    const curr = new Array(n + 1).fill(0);
    for (let j = i + 1; j <= n; j++) {
      if (s[i - 1] === s[j - 1]) {
        curr[j] = prev[j - 1] + 1;
        best = Math.max(best, curr[j]);
      }
    }
    prev = curr;
  }
  return best;
}

