function longestRepeatingSubstring(s) {
  for (let length = s.length - 1; length > 0; length--) {
    const pieces = new Set();
    for (let start = 0; start + length <= s.length; start++) {
      const piece = s.slice(start, start + length);
      if (pieces.has(piece)) return length;
      pieces.add(piece);
    }
  }
  return 0;
}

