function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = k => letters[Math.floor(rand() * k)];
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const k = 1 + Math.floor(rand() * 4);
    return [Array.from({ length: n }, () => pick(k)).join('')];
  }
  const n = 1500 + Math.floor(rand() * 501);
  const shape = Math.floor(rand() * 4);
  if (shape === 0) return [Array.from({ length: n }, () => pick(26)).join('')];
  if (shape === 1) return [Array.from({ length: n }, () => pick(2)).join('')];
  if (shape === 2) return [Array.from({ length: n }, () => (rand() < 0.01 ? pick(26) : 'a')).join('')];
  // A random block copied twice with noise around it, so the answer is long but not trivial.
  const block = Array.from({ length: 300 + Math.floor(rand() * 400) }, () => pick(26)).join('');
  let text = '';
  while (text.length < n) text += rand() < 0.3 ? block : pick(26);
  return [text.slice(0, n)];
}
